import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;
  const group = new Group();

  const activeTimelines = [];
  const disposables = [];

  // 1. Core Sprite Plane (Atlas region: 0, 0, 512, 320 -> Aspect Ratio 1.6)
  const width = 3.2;
  const height = 2.0;
  const geometry = new PlaneGeometry(width, height);
  disposables.push(geometry);

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false
  });
  disposables.push(material);

  // Load the sprite texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.colorNode = texture(tex, uv());
      material.needsUpdate = true;
    });
  }

  const spriteMesh = new Mesh(geometry, material);
  group.add(spriteMesh);

  // 2. Text Component ("Journal")
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const titleItem = textItems.find(t => t.role === 'headline') || textItems[0] || { text: 'Journal' };

  // Render text from fontAtlas as per requirement
  const textMesh = ctx.fontAtlas.createText(titleItem.text, {
    fontSize: 56,
    color: '#e8ecf2',
    align: 'center'
  });

  // Scale down the MSDF output to fit Unit Coordinates beautifully
  textMesh.position.set(0, 0.08, 0.02);
  textMesh.scale.setScalar(0.0125);
  group.add(textMesh);

  // 3. Precision Accent Element (Nova Atelier Signal Red Line)
  const accentGeo = new PlaneGeometry(0.5, 0.015);
  const accentMat = new MeshBasicNodeMaterial({ color: '#ff2a38' });
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(0, -0.32, 0.02);
  group.add(accentMesh);
  disposables.push(accentGeo, accentMat);

  // 4. Subtle Entrance Motion
  const entryTl = gsap.timeline();
  entryTl.fromTo(group.position,
    { y: group.position.y - 0.2 },
    { y: group.position.y, duration: 0.85, ease: 'power3.out' }
  );
  entryTl.fromTo(group.scale,
    { x: 0.9, y: 0.9, z: 0.9 },
    { x: 1, y: 1, z: 1, duration: 1.0, ease: 'power4.out' },
    '<'
  );
  activeTimelines.push(entryTl);

  // 5. Cleanup Hook
  group.userData = {
    handlers: {},
    cleanup: () => {
      activeTimelines.forEach(tl => tl.kill());
      disposables.forEach(d => d.dispose());
    }
  };

  return group;
}
